/* Mini Crossword — a daily 5x5 crossword (newspaper "mini" style), plus an
 * archive of past dailies and random puzzles from the whole set.
 *
 * DATA: crossword-data.js is pre-generated by build-puzzles.js from the
 * hand-written clues.tsv and loaded on first open (precached for offline).
 * Each puzzle is one string: 25 grid cells then its clues; numbering is
 * derived here from the grid. Daily puzzle = days since the data's epoch,
 * modulo the number of puzzles, so everyone gets the same one on a date.
 *
 * PLAY: click a cell (click it again to switch Across/Down), type to fill —
 * the cursor skips to the next empty square, then the next clue. Backspace
 * goes back, arrows move (a perpendicular arrow just turns), Tab / Enter jump
 * to the next clue (Shift for previous), Space turns, Esc closes. Check and
 * Reveal work on a letter, word or the whole puzzle. On touch screens an
 * on-screen A-Z keyboard is used so the system keyboard never pops up.
 * Progress is saved per puzzle; stats track best time and the daily streak.
 *
 * Self-contained IIFE. */
(function () {
  'use strict';
  if (typeof window.Cade === 'undefined') return;
  var Cade = window.Cade;
  Cade.loadCSS('crossword.css');
  var DATA_URL = Cade.asset('crossword-data.js'); // resolve now, while currentScript is us

  var PANEL_ID = 'crossword-panel';
  var PROG_KEY = 'cade-xword-progress', STATS_KEY = 'cade-xword-stats', PREFS_KEY = 'cade-xword-prefs';
  var MAX_OPEN = 30;          // unfinished puzzles kept in progress
  var MAX_DONE = 500;         // finished puzzles remembered (compact) for the archive ticks
  var ARCHIVE_DAYS = 120;
  var N = 5;
  var ICON = "<svg viewBox='0 0 24 24' fill='none' stroke='currentColor' stroke-width='1.8' stroke-linejoin='round'><rect x='3' y='3' width='18' height='18' rx='1.5'/><path d='M9 3v18M15 3v18M3 9h18M3 15h18'/><rect x='3' y='3' width='6' height='6' fill='currentColor'/><rect x='15' y='15' width='6' height='6' fill='currentColor'/></svg>";

  var data = null, loading = null;
  var puz = null;             // parsed puzzle on screen
  var cur = null;             // its progress record { g:[], m:[], t, d, a, u }
  var view = null;            // { idx, date } — date '' for a random pick
  var progress = {}, stats = {}, prefs = {};
  var ui = null;
  var sel = 0, dir = 'A', paused = false, active = true;
  var runSince = 0, tickIv = 0, saveTimer = 0, winTimer = 0, wrongKey = '';

  // ---- helpers -------------------------------------------------------------------
  function readJSON(k, d) { try { var v = JSON.parse(Cade.store.get(k) || 'null'); return v == null ? d : v; } catch (e) { return d; } }
  function writeJSON(k, v) { try { Cade.store.set(k, JSON.stringify(v)); } catch (e) {} }
  function pad2(n) { return (n < 10 ? '0' : '') + n; }
  function dateKey(d) { return d.getFullYear() + '-' + pad2(d.getMonth() + 1) + '-' + pad2(d.getDate()); }
  function today() { return dateKey(new Date()); }
  function dayNum(s) { var p = String(s).split('-'); return Math.round(Date.UTC(+p[0], +p[1] - 1, +p[2]) / 86400000); }
  function numDate(n) { var d = new Date(n * 86400000); return d.getUTCFullYear() + '-' + pad2(d.getUTCMonth() + 1) + '-' + pad2(d.getUTCDate()); }
  function prettyDate(s, long) {
    var p = String(s).split('-');
    try { return new Date(+p[0], +p[1] - 1, +p[2]).toLocaleDateString(undefined, long ? { weekday: 'long', month: 'long', day: 'numeric' } : { weekday: 'short', month: 'short', day: 'numeric' }); } catch (e) { return s; }
  }
  function fmtTime(ms) {
    var s = Math.floor((ms || 0) / 1000), h = Math.floor(s / 3600), m = Math.floor(s / 60) % 60;
    s %= 60;
    return (h ? h + ':' + pad2(m) : m) + ':' + pad2(s);
  }
  function now() { return (window.performance && performance.now) ? performance.now() : Date.now(); }
  function esc(s) { return Cade.escapeHtml(String(s)); }
  function toast(msg, type) { try { Cade.showToast(msg, type || 'info', 2200); } catch (e) {} }
  function dailyIndex(date) { var n = data.p.length; return ((dayNum(date) - dayNum(data.epoch)) % n + n) % n; }

  // ---- data ---------------------------------------------------------------------
  function load() {
    if (data) return Promise.resolve();
    if (window.__cadeCrosswordData) { data = window.__cadeCrosswordData; return Promise.resolve(); }
    if (loading) return loading;
    loading = new Promise(function (resolve, reject) {
      var s = document.createElement('script');
      s.src = DATA_URL;
      s.async = true;
      s.onload = function () {
        if (window.__cadeCrosswordData && window.__cadeCrosswordData.p) { data = window.__cadeCrosswordData; resolve(); }
        else { loading = null; reject(new Error('no data')); }
      };
      s.onerror = function () { loading = null; s.remove(); reject(new Error('load failed')); };
      document.head.appendChild(s);
    });
    return loading;
  }

  // Numbering follows the standard rule (a white cell starting an across or a
  // down entry gets the next number), matching build-puzzles.js.
  function parse(idx) {
    var f = data.p[idx].split('|'), g = f[0], num = [], across = [], down = [], n = 0, at = [];
    function white(r, c) { return r >= 0 && r < N && c >= 0 && c < N && g.charAt(r * N + c) !== '#'; }
    for (var r = 0; r < N; r++) for (var c = 0; c < N; c++) {
      if (!white(r, c)) continue;
      var sa = !white(r, c - 1) && white(r, c + 1), sd = !white(r - 1, c) && white(r + 1, c), k;
      if (sa || sd) num[r * N + c] = ++n;
      if (sa) { var ca = []; for (k = c; white(r, k); k++) ca.push(r * N + k); across.push({ num: n, dir: 'A', cells: ca }); }
      if (sd) { var cd = []; for (k = r; white(k, c); k++) cd.push(k * N + c); down.push({ num: n, dir: 'D', cells: cd }); }
    }
    var slots = across.concat(down);
    slots.forEach(function (s, i) {
      s.i = i; s.clue = f[i + 1] || '';
      s.cells.forEach(function (x) { (at[x] = at[x] || {})[s.dir] = i; });
    });
    return { idx: idx, sol: g, num: num, slots: slots, across: across, down: down, at: at };
  }

  // ---- persistence ----------------------------------------------------------------
  function loadState() {
    progress = readJSON(PROG_KEY, {});
    if (!progress || typeof progress !== 'object') progress = {};
    stats = readJSON(STATS_KEY, {});
    if (!stats || typeof stats !== 'object') stats = {};
    prefs = readJSON(PREFS_KEY, {});
    if (!prefs || typeof prefs !== 'object') prefs = {};
  }
  function record(p) {
    var r = progress[p.idx], g = [], m = [], k;
    var ok = r && typeof r.g === 'string' && r.g.length === 25 && typeof r.m === 'string' && r.m.length === 25;
    for (k = 0; k < 25; k++) {
      var black = p.sol.charAt(k) === '#';
      if (black) { g.push('#'); m.push('0'); continue; }
      if (ok) { var ch = r.g.charAt(k); g.push(/[A-Z]/.test(ch) ? ch : ''); m.push(/[cxr]/.test(r.m.charAt(k)) ? r.m.charAt(k) : '0'); }
      else if (r && r.d) { g.push(p.sol.charAt(k)); m.push('0'); }   // finished, stored compactly
      else { g.push(''); m.push('0'); }
    }
    return { g: g, m: m, t: r ? +r.t || 0 : 0, d: r ? +r.d || 0 : 0, a: r ? +r.a || 0 : 0, u: Date.now() };
  }
  function saveProgress() {
    clearTimeout(saveTimer); saveTimer = 0;
    if (puz && cur) {
      foldClock();
      cur.u = Date.now();
      progress[puz.idx] = cur.d
        ? { d: cur.d, t: Math.round(cur.t), a: cur.a, u: cur.u }
        : { g: cur.g.map(function (c) { return c || ' '; }).join(''), m: cur.m.join(''), t: Math.round(cur.t), d: 0, a: cur.a, u: cur.u };
    }
    // Keep storage small: a few recent unfinished grids + compact finished ticks.
    var keys = Object.keys(progress), open = [], done = [];
    keys.forEach(function (k) { (progress[k] && progress[k].d ? done : open).push(k); });
    function trim(list, max) {
      if (list.length <= max) return;
      list.sort(function (a, b) { return (progress[b].u || 0) - (progress[a].u || 0); });
      list.slice(max).forEach(function (k) { delete progress[k]; });
    }
    trim(open, MAX_OPEN); trim(done, MAX_DONE);
    writeJSON(PROG_KEY, progress);
  }
  function saveSoon() { if (!saveTimer) saveTimer = setTimeout(saveProgress, 400); }
  function savePrefs() { writeJSON(PREFS_KEY, prefs); }

  // ---- clock ---------------------------------------------------------------------
  function elapsed() { return cur ? cur.t + (runSince ? now() - runSince : 0) : 0; }
  function foldClock() { if (runSince && cur) { var n = now(); cur.t += n - runSince; runSince = n; } }
  function stopClock() { foldClock(); runSince = 0; }
  function canRun() { return !!(ui && cur && !cur.d && !paused && !ui.ovKind && !document.hidden); }
  function syncClock() { if (canRun()) { if (!runSince) runSince = now(); } else stopClock(); paintTime(); }
  function paintTime() {
    if (!ui) return;
    var txt = !cur ? '' : cur.d ? '✓ ' + fmtTime(cur.t) : fmtTime(elapsed());
    if (ui.time.textContent !== txt) ui.time.textContent = txt;
  }

  // ---- navigation -------------------------------------------------------------------
  function white(i) { return i >= 0 && i < 25 && puz.sol.charAt(i) !== '#'; }
  function slotOf(i, d) { var a = puz.at[i]; return a && a[d] !== undefined ? puz.slots[a[d]] : null; }
  function curSlot() { return slotOf(sel, dir) || slotOf(sel, dir === 'A' ? 'D' : 'A'); }
  function fixDir() { if (!slotOf(sel, dir)) dir = dir === 'A' ? 'D' : 'A'; }
  function locked(i) { return cur.m[i] === 'c' || cur.m[i] === 'r'; }
  function firstEmpty(s) { for (var k = 0; k < s.cells.length; k++) if (!cur.g[s.cells[k]]) return s.cells[k]; return -1; }
  function gotoSlot(s, preferEmpty) {
    var e = preferEmpty ? firstEmpty(s) : -1;
    sel = e >= 0 ? e : s.cells[0];
    dir = s.dir;
  }
  function stepSlot(delta, needEmpty) {
    var list = puz.slots, i = curSlot().i;
    for (var k = 1; k <= list.length; k++) {
      var s = list[(i + delta * k + list.length * 4) % list.length];
      if (!needEmpty || firstEmpty(s) >= 0) { gotoSlot(s, true); return true; }
    }
    return false;
  }
  // After a letter: next empty square in this word (wrapping), else the next
  // clue with an empty square; overwriting a filled square just steps on.
  function advance(wasFilled) {
    var s = curSlot(), pos = s.cells.indexOf(sel), k;
    if (wasFilled && pos < s.cells.length - 1) { sel = s.cells[pos + 1]; return; }
    for (k = 1; k < s.cells.length; k++) {
      var c = s.cells[(pos + k) % s.cells.length];
      if (!cur.g[c]) { sel = c; return; }
    }
    if (!stepSlot(1, true) && pos < s.cells.length - 1) sel = s.cells[pos + 1];
  }
  function moveArrow(dr, dc) {
    var want = dr ? 'D' : 'A';
    if (dir !== want && slotOf(sel, want)) { dir = want; return; }   // a perpendicular arrow just turns
    var r = (sel / N) | 0, c = sel % N;
    for (;;) {
      r += dr; c += dc;
      if (r < 0 || r >= N || c < 0 || c >= N) return;
      if (white(r * N + c)) { sel = r * N + c; fixDir(); return; }
    }
  }

  // ---- editing -----------------------------------------------------------------------
  function playable() { return !!(ui && puz && cur && !cur.d && !paused && !ui.ovKind); }
  function changed() { wrongKey = ''; saveSoon(); }
  function typeLetter(L) {
    if (!playable()) return;
    var was = !!cur.g[sel];
    if (!locked(sel)) { cur.g[sel] = L; cur.m[sel] = '0'; changed(); }
    advance(was);
    render();
    checkDone();
  }
  function backspace() {
    if (!playable()) return;
    if (cur.g[sel] && !locked(sel)) { cur.g[sel] = ''; cur.m[sel] = '0'; changed(); render(); return; }
    var s = curSlot(), pos = s.cells.indexOf(sel);
    if (pos > 0) sel = s.cells[pos - 1];
    else { var prev = puz.slots[(s.i - 1 + puz.slots.length) % puz.slots.length]; sel = prev.cells[prev.cells.length - 1]; dir = prev.dir; }
    if (cur.g[sel] && !locked(sel)) { cur.g[sel] = ''; cur.m[sel] = '0'; changed(); }
    render();
  }
  function del() {
    if (!playable() || locked(sel) || !cur.g[sel]) return;
    cur.g[sel] = ''; cur.m[sel] = '0'; changed(); render();
  }
  function scopeCells(scope) {
    if (scope === 'letter') return [sel];
    if (scope === 'word') return curSlot().cells.slice();
    var all = [];
    for (var k = 0; k < 25; k++) if (white(k)) all.push(k);
    return all;
  }
  function check(scope) {
    if (!playable()) return;
    var bad = 0, empty = 0;
    scopeCells(scope).forEach(function (c) {
      if (cur.m[c] === 'r') return;
      if (!cur.g[c]) { empty++; return; }
      if (cur.g[c] === puz.sol.charAt(c)) cur.m[c] = 'c';
      else { cur.m[c] = 'x'; bad++; }
    });
    changed(); render();
    if (bad) toast(bad === 1 ? '1 square is wrong' : bad + ' squares are wrong', 'error');
    else toast(empty ? 'Correct so far' : 'All correct', 'success');
  }
  function reveal(scope) {
    if (!playable()) return;
    if (scope === 'puzzle' && !window.confirm('Reveal the whole puzzle? It will count as assisted (no streak or best time).')) return;
    var any = false;
    scopeCells(scope).forEach(function (c) {
      if (cur.g[c] === puz.sol.charAt(c) && cur.m[c] !== 'x') return;
      cur.g[c] = puz.sol.charAt(c); cur.m[c] = 'r'; any = true;
    });
    if (any) cur.a = 1;
    changed(); render(); checkDone();
  }
  function clearAll() {
    if (!cur || cur.d) return;
    if (!window.confirm('Clear every square? (The clock keeps running.)')) return;
    for (var k = 0; k < 25; k++) if (white(k) && cur.m[k] !== 'r') { cur.g[k] = ''; cur.m[k] = '0'; }
    changed(); render();
  }
  function checkDone() {
    for (var k = 0; k < 25; k++) if (white(k) && !cur.g[k]) return;
    for (k = 0; k < 25; k++) {
      if (white(k) && cur.g[k] !== puz.sol.charAt(k)) {
        var key = cur.g.join('');
        if (wrongKey !== key) { wrongKey = key; toast('Not quite — at least one square is off', 'error'); }
        return;
      }
    }
    win();
  }

  function win() {
    stopClock();
    cur.d = cur.a ? 2 : 1;
    var t = cur.t, td = today(), isDaily = puz.idx === dailyIndex(td) && (!view.date || view.date === td);
    var newBest = false, streak = 0;
    if (!cur.a) {
      stats.solved = (stats.solved || 0) + 1;
      stats.tot = (stats.tot || 0) + t;
      if (!stats.best || t < stats.best) { newBest = !!stats.best; stats.best = t; }
      if (isDaily && stats.last !== td) {
        var y = numDate(dayNum(td) - 1);
        stats.streak = stats.last === y ? (stats.streak || 0) + 1 : 1;
        stats.max = Math.max(stats.max || 0, stats.streak);
        stats.last = td;
      }
    } else stats.assisted = (stats.assisted || 0) + 1;
    streak = currentStreak();
    writeJSON(STATS_KEY, stats);
    saveProgress();
    render();
    try { Cade.haptic(30); } catch (e) {}
    if (!ui) return;
    ui.grid.classList.add('won');
    var html = '<div class="xw-card"><div class="xw-big">' + (cur.a ? '👍' : '🎉') + '</div>' +
      '<b class="xw-title">' + (cur.a ? 'Finished' : 'You solved it!') + '</b>' +
      '<div class="xw-sub">' + esc(headLabel()) + '</div>' +
      '<div class="xw-wintime">' + fmtTime(t) + '</div>' +
      '<div class="xw-sub">' + (cur.a ? 'Revealed squares — not counted in stats' : newBest ? 'New best time!' : 'Best ' + fmtTime(stats.best)) + '</div>' +
      (isDaily && !cur.a ? '<div class="xw-sub">Daily streak 🔥 ' + streak + '</div>' : '') +
      '<div class="xw-acts"><button class="xw-primary" data-act="puzzles">More puzzles</button><button data-act="stats">Stats</button><button data-act="hide">View grid</button></div></div>';
    var p = puz;
    clearTimeout(winTimer);
    winTimer = setTimeout(function () { if (ui && puz === p) showOverlay('win', html); }, 1000);
  }
  function currentStreak() {
    var td = today(), y = numDate(dayNum(td) - 1);
    return stats.last === td || stats.last === y ? stats.streak || 0 : 0;
  }

  // ---- opening puzzles -------------------------------------------------------------
  function openPuzzle(idx, date) {
    if (puz && cur) { stopClock(); saveProgress(); }
    clearTimeout(winTimer);
    puz = parse(idx);
    view = { idx: idx, date: date || '' };
    cur = record(puz);
    paused = false; wrongKey = '';
    prefs.idx = idx; prefs.date = view.date; prefs.day = today(); savePrefs();
    sel = 0; dir = 'A';
    while (!white(sel)) sel++;
    var first = puz.slots.filter(function (s) { return firstEmpty(s) >= 0; })[0];
    if (first) gotoSlot(first, true);
    fixDir();
    if (ui) { ui.grid.classList.remove('won'); buildGrid(); buildClues(); hideOverlay(); }
    render();
  }
  function openToday() { var td = today(); openPuzzle(dailyIndex(td), td); }
  function openRandom() {
    var n = data.p.length, pick = -1, tries = 0;
    while (tries++ < 60) {
      var i = (Math.random() * n) | 0;
      if (puz && i === puz.idx) continue;
      pick = i;
      if (!progress[i] || !progress[i].d) break;   // prefer one you haven't finished
    }
    openPuzzle(pick < 0 ? 0 : pick, '');
  }
  function headLabel() {
    if (!view) return 'Mini Crossword';
    if (view.date) return (view.date === today() ? 'Today' : prettyDate(view.date)) + ' · #' + (view.idx + 1);
    return 'Puzzle #' + (view.idx + 1);
  }

  // ---- overlays --------------------------------------------------------------------
  function showOverlay(kind, html) {
    if (!ui) return;
    closeMenu();
    ui.ovKind = kind;
    ui.ov.className = 'xw-ov show xw-ov-' + kind;
    ui.ov.innerHTML = html;
    ui.main.classList.toggle('xw-veil', kind !== 'win' && kind !== 'msg');
    syncClock();
  }
  function hideOverlay() {
    if (!ui) return;
    ui.ovKind = '';
    ui.ov.className = 'xw-ov';
    ui.ov.innerHTML = '';
    ui.main.classList.remove('xw-veil');
    syncClock();
  }
  function pause() {
    if (!cur || cur.d || !ui || ui.ovKind) return;
    paused = true;
    showOverlay('pause', '<div class="xw-card"><b class="xw-title">Paused</b><div class="xw-wintime">' + fmtTime(elapsed()) + '</div>' +
      '<div class="xw-acts"><button class="xw-primary" data-act="unpause">Resume</button></div></div>');
  }
  function unpause() { paused = false; hideOverlay(); }

  function statusOf(idx) {
    var r = progress[idx];
    if (!r) return '';
    if (r.d) return '<span class="xw-st ok">✓ ' + fmtTime(r.t) + (r.d === 2 ? '*' : '') + '</span>';
    if (/[A-Z]/.test(r.g || '')) return '<span class="xw-st part">in progress</span>';
    return '';
  }
  function puzzlesMenu() {
    var td = today(), tn = dayNum(td), first = Math.max(dayNum(data.epoch), tn - ARCHIVE_DAYS + 1), rows = '';
    for (var d = tn - 1; d >= first; d--) {
      var ds = numDate(d), i = dailyIndex(ds);
      rows += '<button class="xw-row" data-act="open" data-i="' + i + '" data-date="' + ds + '"><span>' + esc(prettyDate(ds)) +
        ' <i>#' + (i + 1) + '</i></span>' + statusOf(i) + '</button>';
    }
    var ti = dailyIndex(td);
    showOverlay('menu', '<div class="xw-card xw-pz"><b class="xw-title">Puzzles</b>' +
      '<button class="xw-row xw-today" data-act="open" data-i="' + ti + '" data-date="' + td + '"><span><b>Today</b> · ' + esc(prettyDate(td, true)) + '</span>' + statusOf(ti) + '</button>' +
      '<button class="xw-row" data-act="random"><span>🎲 Random puzzle <i>(' + data.p.length + ' in all)</i></span></button>' +
      (rows ? '<div class="xw-h">Archive</div><div class="xw-arch">' + rows + '</div>' : '') +
      '<div class="xw-acts"><button data-act="hide">Close</button></div></div>');
  }
  function statsMenu() {
    var avg = stats.solved ? fmtTime(stats.tot / stats.solved) : '—';
    function cell(v, l) { return '<div class="xw-stat"><b>' + v + '</b><span>' + l + '</span></div>'; }
    showOverlay('stats', '<div class="xw-card"><b class="xw-title">Statistics</b><div class="xw-stats">' +
      cell(stats.solved || 0, 'Solved') + cell(stats.best ? fmtTime(stats.best) : '—', 'Best time') + cell(avg, 'Average') +
      cell(currentStreak(), 'Streak') + cell(stats.max || 0, 'Longest') + cell(stats.assisted || 0, 'Assisted') +
      '</div><div class="xw-sub">Streaks count dailies solved on their own day without reveals.</div>' +
      '<div class="xw-acts"><button data-act="resetstats">Reset</button><button class="xw-primary" data-act="hide">Close</button></div></div>');
  }

  // ---- in-panel dropdown (check / reveal / more) ---------------------------------
  function closeMenu() { if (ui && ui.menu) { ui.menu.remove(); ui.menu = null; } }
  function openMenu(btn) {
    if (ui.menu) { var same = ui.menu._for === btn; closeMenu(); if (same) return; }
    var m = document.createElement('div');
    m.className = 'xw-menu';
    m._for = btn;
    var live = cur && !cur.d;
    m.innerHTML = (live ? '<div class="xw-mh">Check</div><div class="xw-mrow"><button data-act="chk-letter">Letter</button><button data-act="chk-word">Word</button><button data-act="chk-puzzle">Puzzle</button></div>' +
      '<div class="xw-mh">Reveal</div><div class="xw-mrow"><button data-act="rev-letter">Letter</button><button data-act="rev-word">Word</button><button data-act="rev-puzzle">Puzzle</button></div>' +
      '<button class="xw-mi" data-act="clear">⌫ Clear puzzle</button>' : '') +
      '<button class="xw-mi" data-act="stats">📊 Statistics</button>' +
      '<div class="xw-mkeys">Type letters · click a square twice or Space to turn · Tab / Enter next clue · arrows move · Esc close</div>';
    ui.root.appendChild(m);
    ui.menu = m;
  }

  function onAct(act, el) {
    if (act === 'hide') hideOverlay();
    else if (act === 'unpause') unpause();
    else if (act === 'puzzles') puzzlesMenu();
    else if (act === 'stats') statsMenu();
    else if (act === 'random') openRandom();
    else if (act === 'open') openPuzzle(+el.getAttribute('data-i'), el.getAttribute('data-date') || '');
    else if (act === 'clear') { closeMenu(); clearAll(); }
    else if (act === 'retry') { close(); open(); }
    else if (act === 'resetstats') { if (window.confirm('Reset crossword statistics?')) { stats = {}; writeJSON(STATS_KEY, stats); statsMenu(); } }
    else if (/^(chk|rev)-/.test(act)) {
      closeMenu();
      var scope = act.slice(4);
      if (act.indexOf('chk') === 0) check(scope); else reveal(scope);
    }
  }

  // ---- rendering --------------------------------------------------------------------
  function buildGrid() {
    var h = '';
    for (var k = 0; k < 25; k++) {
      var r = (k / N) | 0, c = k % N;
      if (!white(k)) { h += '<div class="xw-cell blk" style="--d:' + (r + c) + '"></div>'; continue; }
      h += '<div class="xw-cell" data-i="' + k + '" style="--d:' + (r + c) + '">' +
        (puz.num[k] ? '<span class="xw-num">' + puz.num[k] + '</span>' : '') + '<span class="xw-let"></span></div>';
    }
    ui.grid.innerHTML = h;
    ui.cells = [];
    ui.grid.querySelectorAll('.xw-cell[data-i]').forEach(function (el) { ui.cells[+el.getAttribute('data-i')] = el; });
  }
  function buildClues() {
    function col(list, title) {
      return '<div class="xw-col"><div class="xw-h">' + title + '</div><ol>' + list.map(function (s) {
        return '<li data-s="' + s.i + '"><b>' + s.num + '</b><span>' + esc(s.clue) + '</span></li>';
      }).join('') + '</ol></div>';
    }
    ui.clues.innerHTML = col(puz.across, 'Across') + col(puz.down, 'Down');
    ui.clueEls = [];
    ui.clues.querySelectorAll('li[data-s]').forEach(function (el) { ui.clueEls[+el.getAttribute('data-s')] = el; });
  }
  function render() {
    if (!ui || !puz) return;
    ui.title.textContent = headLabel();
    paintTime();
    var done = !!cur.d, s = curSlot(), other = slotOf(sel, s.dir === 'A' ? 'D' : 'A');
    ui.root.classList.toggle('xw-done', done);
    for (var k = 0; k < 25; k++) {
      var el = ui.cells[k];
      if (!el) continue;
      var cls = 'xw-cell';
      if (!done && k === sel) cls += ' sel';
      else if (!done && s.cells.indexOf(k) !== -1) cls += ' word';
      var m = cur.m[k];
      if (m === 'x') cls += ' bad'; else if (m === 'c') cls += ' ok'; else if (m === 'r') cls += ' rev';
      if (el.className !== cls) el.className = cls;
      var lt = el.lastChild, L = cur.g[k] || '';
      if (lt.textContent !== L) lt.textContent = L;
    }
    ui.barNum.textContent = s.num + (s.dir === 'A' ? 'A' : 'D');
    ui.barText.textContent = s.clue;
    ui.clueEls.forEach(function (li, i) {
      var sl = puz.slots[i], full = true;
      for (var q = 0; q < sl.cells.length; q++) if (!cur.g[sl.cells[q]]) { full = false; break; }
      var c = (i === s.i && !done ? 'on' : other && i === other.i && !done ? 'cross' : '') + (full ? ' full' : '');
      if (li.className !== c) li.className = c;
    });
    var on = ui.clueEls[s.i];
    if (on && !done) {
      var box = on.parentNode.parentNode;
      if (box.scrollHeight > box.clientHeight + 2) {
        var top = on.offsetTop - box.offsetTop;
        if (top < box.scrollTop || top + on.offsetHeight > box.scrollTop + box.clientHeight) box.scrollTop = Math.max(0, top - 24);
      }
    }
  }

  // ---- panel ------------------------------------------------------------------------
  function panelHtml() {
    var rows = ['QWERTYUIOP', 'ASDFGHJKL', 'ZXCVBNM'], kb = '';
    rows.forEach(function (r, ri) {
      kb += '<div class="xw-kr">';
      for (var k = 0; k < r.length; k++) kb += '<button data-k="' + r[k] + '">' + r[k] + '</button>';
      if (ri === 2) kb += '<button class="xw-kbs" data-k="BS" aria-label="Backspace">⌫</button>';
      kb += '</div>';
    });
    return '<div class="xw" tabindex="-1">' +
      '<div class="xw-top"><span class="xw-ttl"></span><span class="xw-time" title="Pause"></span>' +
        '<button class="xw-btn" data-tool="pause" title="Pause" aria-label="Pause">⏸</button>' +
        '<button class="xw-btn" data-tool="puzzles" title="Today, archive & random">Puzzles</button>' +
        '<button class="xw-btn" data-tool="menu" title="Check, reveal, stats">Check ▾</button></div>' +
      '<div class="xw-main">' +
        '<div class="xw-left">' +
          '<div class="xw-bar"><button class="xw-arrow" data-tool="prev" aria-label="Previous clue">‹</button>' +
            '<div class="xw-cur" data-tool="turn"><b class="xw-cn"></b><span class="xw-ct"></span></div>' +
            '<button class="xw-arrow" data-tool="next" aria-label="Next clue">›</button></div>' +
          '<div class="xw-grid"></div>' +
        '</div>' +
        '<div class="xw-clues"></div>' +
        '<div class="xw-ov"></div>' +
      '</div>' +
      '<div class="xw-kb">' + kb + '</div></div>';
  }

  function close() {
    var p = document.getElementById(PANEL_ID);
    if (p) p.remove();
    teardown();
    try { Cade.editor.focus(); } catch (e) {}
  }
  function teardown() {
    if (!ui) return;
    stopClock();
    saveProgress();
    clearInterval(tickIv); tickIv = 0;
    clearTimeout(winTimer);
    document.removeEventListener('keydown', ui.onKey, true);
    document.removeEventListener('pointerdown', ui.onDocDown, true);
    document.removeEventListener('visibilitychange', ui.onVis);
    window.removeEventListener('pagehide', ui.onHide);
    ui = null;
  }

  function open() {
    Cade.closeAllMenus();
    if (document.getElementById(PANEL_ID)) { close(); return; }
    loadState();
    var p = Cade.mkPanel(PANEL_ID, '▦ Mini Crossword', panelHtml());
    var root = p.querySelector('.xw');
    ui = {
      panel: p, root: root, main: root.querySelector('.xw-main'), grid: root.querySelector('.xw-grid'),
      clues: root.querySelector('.xw-clues'), ov: root.querySelector('.xw-ov'), title: root.querySelector('.xw-ttl'),
      time: root.querySelector('.xw-time'), barNum: root.querySelector('.xw-cn'), barText: root.querySelector('.xw-ct'),
      cells: [], clueEls: [], ovKind: '', menu: null
    };
    active = true; paused = false;
    p._onClose = teardown;

    ui.onDocDown = function (e) {
      if (!ui) return;
      active = ui.panel.contains(e.target);
      ui.root.classList.toggle('xw-idle', !active);
      if (ui.menu && !ui.menu.contains(e.target) && !(e.target.closest && e.target.closest('[data-tool="menu"]'))) closeMenu();
    };
    ui.onKey = onKey;
    ui.onVis = function () {
      if (!ui) return;
      if (document.hidden) { if (cur && !cur.d && !ui.ovKind) pause(); saveProgress(); }
      syncClock();
    };
    ui.onHide = function () { saveProgress(); };
    document.addEventListener('keydown', ui.onKey, true);
    document.addEventListener('pointerdown', ui.onDocDown, true);
    document.addEventListener('visibilitychange', ui.onVis);
    window.addEventListener('pagehide', ui.onHide);

    // Keep focus on the panel (no text selection, no soft keyboard).
    root.addEventListener('pointerdown', function (e) {
      if (e.button > 0) return;
      e.preventDefault();
      try { root.focus({ preventScroll: true }); } catch (x) {}
      var cell = e.target.closest('.xw-cell[data-i]');
      if (cell && playable()) {
        var i = +cell.getAttribute('data-i');
        if (i === sel) dir = dir === 'A' ? 'D' : 'A'; else sel = i;
        fixDir(); render();
      }
    });
    root.addEventListener('click', function (e) {
      var t = e.target, el;
      if ((el = t.closest('[data-act]'))) { onAct(el.getAttribute('data-act'), el); return; }
      if ((el = t.closest('[data-k]'))) { var k = el.getAttribute('data-k'); if (k === 'BS') backspace(); else typeLetter(k); return; }
      if ((el = t.closest('li[data-s]'))) { if (playable()) { gotoSlot(puz.slots[+el.getAttribute('data-s')], true); render(); } return; }
      if (!(el = t.closest('[data-tool]'))) return;
      var a = el.getAttribute('data-tool');
      if (a === 'pause') { if (paused) unpause(); else pause(); }
      else if (a === 'puzzles') { if (data) puzzlesMenu(); }
      else if (a === 'menu') { if (data) openMenu(el); }
      else if (!playable()) return;
      else if (a === 'prev') { stepSlot(-1, false); render(); }
      else if (a === 'next') { stepSlot(1, false); render(); }
      else if (a === 'turn') { dir = dir === 'A' ? 'D' : 'A'; fixDir(); render(); }
    });
    ui.time.addEventListener('click', function () { if (paused) unpause(); else pause(); });

    try { Cade.editor.contentDOM.blur(); } catch (e) {}
    try { root.focus({ preventScroll: true }); } catch (e) {}
    showOverlay('msg', '<div class="xw-card xw-msg"><div class="xw-spin"></div>Loading puzzles…</div>');
    load().then(function () {
      if (!ui) return;
      hideOverlay();
      var td = today(), n = data.p.length;
      // Resume the puzzle you were on today if it's unfinished, else today's daily.
      if (prefs.day === td && prefs.idx >= 0 && prefs.idx < n && !(progress[prefs.idx] && progress[prefs.idx].d)) openPuzzle(prefs.idx, prefs.date || '');
      else openToday();
      tickIv = setInterval(paintTime, 500);
      syncClock();
    }, function () {
      if (!ui) return;
      showOverlay('msg', '<div class="xw-card xw-msg">Couldn’t load the puzzles (offline?).<div class="xw-acts"><button class="xw-primary" data-act="retry">Try again</button></div></div>');
    });
  }

  function onKey(e) {
    if (!ui || !active || !puz) return;
    var ae = document.activeElement;
    if (ae && ae !== document.body && !ui.panel.contains(ae)) return; // typing elsewhere (editor, palette…)
    var k = e.key, handled = true;
    if (k === 'Escape') {
      if (ui.menu) closeMenu();
      else if (ui.ovKind && ui.ovKind !== 'pause' && ui.ovKind !== 'msg') hideOverlay();
      else close();
    } else if (e.ctrlKey || e.metaKey || e.altKey) handled = false;
    else if (ui.ovKind) {
      if (ui.ovKind === 'pause' && (k === ' ' || k === 'Enter')) unpause(); else handled = false;
    } else if (!playable()) handled = false;
    else if (/^[a-zA-Z]$/.test(k)) typeLetter(k.toUpperCase());
    else if (k === 'Backspace') backspace();
    else if (k === 'Delete') del();
    else if (k === 'ArrowLeft') { moveArrow(0, -1); render(); }
    else if (k === 'ArrowRight') { moveArrow(0, 1); render(); }
    else if (k === 'ArrowUp') { moveArrow(-1, 0); render(); }
    else if (k === 'ArrowDown') { moveArrow(1, 0); render(); }
    else if (k === 'Tab' || k === 'Enter') { stepSlot(e.shiftKey ? -1 : 1, false); render(); }
    else if (k === ' ') { dir = dir === 'A' ? 'D' : 'A'; fixDir(); render(); }
    else handled = false;
    if (handled) { e.preventDefault(); e.stopPropagation(); }
  }

  Cade.registerWidget({
    name: 'Mini Crossword',
    description: 'Daily 5×5 crossword, plus an archive and random puzzles',
    icon: ICON,
    tags: 'game,crossword,mini,puzzle,words,clues,daily,brain,fun',
    open: open
  });
})();
